class Manacher:
    def __init__(self, input_string) -> None:
        self.input_string = input_string

    def palindromic_length(self, center, diff, string):
        while center >= 0 and center + diff < len(string) and string[center - diff] == string[center + diff]:
            diff += 1
        return diff

    def palindromic_string(self):
        max_length = 0
        center = 0
        for i in range(len(self.input_string)):
            length = self.palindromic_length(i, 1, self.input_string)
            if length > max_length:
                max_length = length
                center = i
        start = center - (max_length - 1) // 2
        return self.input_string[start:start + max_length]

# Example usage:
manacher = Manacher('ababaxse')
print(manacher.palindromic_string())  # Output: 'ababa'
