        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format(123456)
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """

        if isinstance(x, float):
            int_part = int(x)
            decimal_part = int((x - int_part) * 100)
            return self.format_string(f"{int_part}.{decimal_part}") + " ONLY"
        else:
            return self.format_string(x)

    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        :param x: str, the string representation of a number
        :return: str, the number in words format
        """
        if not x.isdigit():
            raise ValueError("Input must be a string representation of a number")

        x = x.replace(',', '')

        if '.' in x:
            integer_part, decimal_part = x.split('.')
        else:
            integer_part, decimal_part = x, ''

        integer_part = self._convert_integer(integer_part)
        decimal_part = self._convert_decimal(decimal_part)

        if decimal_part:
            return f"{integer_part} AND {decimal_part} ONLY"
        else:
            return integer_part

    def _convert_integer(self, x):
        if not x:
            return ""

        digits = len(x)
        words = []

        for i, digit in enumerate(x):
            if digit == '0':
                if digits == 1:
                    words.append(self.NUMBER[int(digit)])
                else:
                    words.append(self.NUMBER[int(digit)] + " ZERO")
            else:
                if digits == 1:
                    words.append(self.NUMBER[int(digit)])
                else:
                    words.append(self.trans_three(x[:i + 1]))

            if (i < digits - 2) and (int(digit) != 0):
                words.append(self.parse_more(digits - 2 - i))

        if not words:
            return ""

        last_word = words.pop()
        if last_word in ["THOUSAND", "MILLION", "BILLION"]:
            words.append("AND")

        return " ".join(words)

    def _convert_decimal(self, x):
        if not x:
            return ""

        if len(x) == 1:
            return self.NUMBER[int(x)]
        elif len(x) == 2:
            if x == "10":
                return "TEN"
            elif x.startswith("0"):
                return "ZERO"
            else:
                return self.NUMBER_TEN[int(x[0])] + (f" {self.NUMBER[int(x[1])]}" if int(x[1]) != 0 else "")
